module pitch_detector (
    input clk,
    input waveform,
    output reg [7:0] pitch_period
);
    reg [7:0] count;
    reg last_waveform;

    always @(posedge clk) begin
        if (waveform && !last_waveform) begin
            pitch_period <= count;
            count <= 0;
        end else begin
            count <= count + 1;
        end
        last_waveform <= waveform;
    end
endmodule

