module pcie_endpoint_controller(  
    input wire clk,  
    input wire rst,  
    input wire req,  
    input wire rw,  
    output reg ack,  
    inout wire [31:0] data  
);  
    reg state;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            ack <= 0;  
            state <= 0;  
        end else if (req) begin  
            ack <= 1;  
            state <= rw;  
        end else begin  
            ack <= 0;  
        end  
    end  
endmodule

