module PLL (
    input wire clk_in,
    input wire reset,
    output reg clk_out,
    output reg locked
);
    parameter DIV_FACTOR = 4; // Parameter to configure output frequency
    reg [3:0] counter;
    reg [1:0] state;

    localparam IDLE = 2'b00,
               LOCKING = 2'b01,
               LOCKED = 2'b10;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            counter <= 0;
            clk_out <= 0;
            locked <= 0;
        end else begin
            case (state)
                IDLE: begin
                    clk_out <= 0;
                    counter <= 0;
                    state <= LOCKING;
                end
                LOCKING: begin
                    if (counter < DIV_FACTOR - 1) begin
                        counter <= counter + 1;
                        clk_out <= (counter == (DIV_FACTOR / 2 - 1)) ? 1 : 0; // Toggle output clock
                    end else begin
                        locked <= 1;
                        state <= LOCKED;
                    end
                end
                LOCKED: begin
                    clk_out <= 1; // Maintain locked output high
                end
            endcase
        end
    end
endmodule

