module LDO_Controller (
    input wire clk,
    input wire reset,
    input wire [7:0] Vref,   // Reference voltage
    input wire [7:0] Vout,   // Output voltage
    output reg PWM           // PWM output to control the pass transistor
);
    reg [7:0] error;
    reg [7:0] duty_cycle;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            PWM <= 0;
            duty_cycle <= 0;
        end else begin
            error <= Vref - Vout;
            if (error > 8'd10) begin  // If error > 10, increase duty cycle
                duty_cycle <= duty_cycle + 1;
            end else if (error < 8'd5) begin  // If error < 5, decrease duty cycle
                duty_cycle <= duty_cycle - 1;
            end

            // Limit the duty cycle between 0 and 255
            if (duty_cycle > 8'd255) begin
                duty_cycle <= 8'd255;
            end else if (duty_cycle < 8'd0) begin
                duty_cycle <= 8'd0;
            end

            // Generate PWM signal
            PWM <= (duty_cycle < Vout) ? 1'b1 : 1'b0;
        end
    end
endmodule

