module adaptive_lms_filter #(parameter N = 5, parameter MU = 8'h01)  
(  
    input clk,  
    input rst,  
    input signed [15:0] x,  
    input signed [15:0] d,  
    output reg signed [15:0] y  
);  

    reg signed [15:0] w [0:N-1];  
    reg signed [15:0] e;  

    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= 16'h0;  
            y <= 16'h0;  
        end else begin  
            // Compute output  
            y <= 16'h0;  
            for (i = 0; i < N; i = i + 1)  
                y <= y + w[i] * x;  

            // Compute error  
            e <= d - y;  

            // Update weights  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= w[i] + (MU * e * x);  
        end  
    end  
endmodule

