module SLAM_Controller (
    input clk,
    input rst,
    input [1:0] move_cmd,
    output reg [7:0] x_pos,
    output reg [7:0] y_pos
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x_pos <= 8'd0;
            y_pos <= 8'd0;
        end else begin
            case (move_cmd)
                2'b00: begin // No move
                    x_pos <= x_pos;
                    y_pos <= y_pos;
                end
                2'b01: begin // Move right
                    x_pos <= x_pos + 1;
                    y_pos <= y_pos;
                end
                2'b10: begin // Move up
                    x_pos <= x_pos;
                    y_pos <= y_pos + 1;
                end
                2'b11: begin // Move left
                    x_pos <= x_pos - 1;
                    y_pos <= y_pos;
                end
                default: begin
                    x_pos <= x_pos;
                    y_pos <= y_pos;
                end
            endcase
        end
    end
endmodule

