module matrix_factorization (
    input clk,
    input rst,
    input [31:0] matrix_in_00,
    input [31:0] matrix_in_01,
    input [31:0] matrix_in_10,
    input [31:0] matrix_in_11,
    output reg [31:0] matrix_out_00,
    output reg [31:0] matrix_out_01,
    output reg [31:0] matrix_out_10,
    output reg [31:0] matrix_out_11
);
    reg [31:0] U_00, U_01, V_00, V_01;
    reg [31:0] temp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            U_00 <= 0; U_01 <= 0;
            V_00 <= 0; V_01 <= 0;
            matrix_out_00 <= 0; matrix_out_01 <= 0;
            matrix_out_10 <= 0; matrix_out_11 <= 0;
        end else begin
            // Simplified SVD for a 2x2 matrix, values used are for demonstration
            U_00 <= matrix_in_00 + matrix_in_01; // Example calculations
            U_01 <= matrix_in_10 + matrix_in_11;
            V_00 <= matrix_in_00 - matrix_in_01;
            V_01 <= matrix_in_10 - matrix_in_11;

            // Calculate the outputs as a product of the simplified U and V
            matrix_out_00 <= U_00 * V_00;
            matrix_out_01 <= U_00 * V_01;
            matrix_out_10 <= U_01 * V_00;
            matrix_out_11 <= U_01 * V_01;
        end
    end
endmodule

