module I2C_Master (  
    input wire clk,  
    input wire reset,  
    input wire start,  
    input wire [7:0] data_in,  
    output reg sda,  
    output reg scl,  
    output reg busy,  
    output reg ack  
);  

    parameter IDLE = 3'b000,  
              START = 3'b001,  
              DATA = 3'b010,  
              ACK = 3'b011,  
              STOP = 3'b100;  

    reg [2:0] state, next_state;  
    reg [3:0] bit_count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            busy <= 0;  
            bit_count <= 0;  
            sda <= 1;  
            scl <= 1;  
            ack <= 0;  
        end else begin  
            state <= next_state;  
        end  
    end  

    always @(*) begin  
        next_state = state;  
        case (state)  
            IDLE: begin  
                if (start) begin  
                    next_state = START;  
                    busy = 1;  
                end  
            end  
            START: begin  
                sda = 0;  
                scl = 0;  
                next_state = DATA;  
            end  
            DATA: begin  
                if (bit_count < 8) begin  
                    sda = data_in[7 - bit_count];  
                    scl = 0;  
                    next_state = ACK;  
                    bit_count = bit_count + 1;  
                end else begin  
                    next_state = STOP;  
                end  
            end  
            ACK: begin  
                scl = 1;  
                ack = (sda == 0) ? 1 : 0;  
                next_state = (ack) ? STOP : IDLE;  
            end  
            STOP: begin  
                sda = 1;  
                scl = 1;  
                busy = 0;  
                next_state = IDLE;  
            end  
        endcase  
    end  
endmodule

