module audio_buffer #(parameter SIZE = 4) (  
    input clk,  
    input reset,  
    input [15:0] audio_in,  
    input write_enable,  
    input read_enable,  
    output reg [15:0] audio_out  
);  
    reg [15:0] buffer [0:SIZE-1];  
    reg [1:0] write_ptr;  
    reg [1:0] read_ptr;  
    reg [2:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            write_ptr <= 0;  
            read_ptr <= 0;  
            count <= 0;  
            audio_out <= 0;  
        end else begin  
            if (write_enable && count < SIZE) begin  
                buffer[write_ptr] <= audio_in;  
                write_ptr <= (write_ptr + 1) % SIZE;  
                count <= count + 1;  
            end  
            if (read_enable && count > 0) begin  
                audio_out <= buffer[read_ptr];  
                read_ptr <= (read_ptr + 1) % SIZE;  
                count <= count - 1;  
            end  
        end  
    end  
endmodule

