        if (rst) begin
            top <= 2'b00;
            full <= 1'b0;
            empty <= 1'b1;
            data_out <= 8'b0;
        end else begin
            if (push && !full) begin
                stack_mem[top] <= data_in;
                top <= top + 1;
                if (top == 2'b11) full <= 1'b1;
                empty <= 1'b0;
            end else if (pop && !empty) begin
                top <= top - 1;
                data_out <= stack_mem[top];
                if (top == 2'b00) empty <= 1'b1;
                full <= 1'b0;
            end
        end
    end
endmodule

