module clock_divider #(parameter N = 2) (  
    input wire clk_in,  
    input wire rst,  
    output reg clk_out  
);  
    integer count;  
    always @(posedge clk_in or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            clk_out <= 0;  
        end else if (count == (N-1)) begin  
            clk_out <= ~clk_out;  
            count <= 0;  
        end else begin  
            count <= count + 1;  
        end  
    end  
endmodule

