            $display("Testcase %0d: Verify WE is required for storage", test_num);


            WE = 1;
            data_in = 16'h1234;
            @(posedge clk);
            #2;


            WE = 0;
            data_in = 16'hFFFF;
            @(posedge clk);
            #2;


            RE = 1;
            #5;

            #1;


            check_outputs(16'h1234);
        end
        endtask

    task testcase004;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Testcase %0d: Boundary Test - All bits high", test_num);

            WE = 1;
            data_in = 16'hFFFF;
            @(posedge clk);
            #2;
            WE = 0;
            RE = 1;
            #5;
            #1;

            check_outputs(16'hFFFF);
        end
        endtask

    task testcase005;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Testcase %0d: Boundary Test - All bits low", test_num);

            WE = 1;
            data_in = 16'h0000;
            @(posedge clk);
            #2;
            WE = 0;
            RE = 1;
            #5;
            #1;

            check_outputs(16'h0000);
        end
        endtask

    task testcase006;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Testcase %0d: Overwriting existing data", test_num);


            WE = 1;
            data_in = 16'h1111;
            @(posedge clk);
            #2;


            data_in = 16'h2222;
            @(posedge clk);
            #2;

            WE = 0;
            RE = 1;
            #5;
            #1;

            check_outputs(16'h2222);
        end
        endtask

    task testcase007;

        begin
            reset_dut();
            test_num = test_num + 1;
            $display("Testcase %0d: Simultaneous Read/Write", test_num);

            WE = 1;
            RE = 1;
            data_in = 16'hC0DE;
            @(posedge clk);
            #5;


            #1;



            check_outputs(16'hC0DE);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("dram_cell Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [15:0] expected_data_out;
        begin
            if (expected_data_out === (expected_data_out ^ data_out ^ expected_data_out)) begin
                $display("PASS");
                $display("  Outputs: data_out=%h",
                         data_out);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: data_out=%h",
                         expected_data_out);
                $display("  Got:      data_out=%h",
                         data_out);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,RE, WE, clk, data_in, data_out);
    end

endmodule
